import sys
import itertools

MOD = 1000000007
INV100 = pow(100, MOD-2, MOD)

def mod_add(a, b):
    return (a + b) % MOD

def mod_sub(a, b):
    return (a - b) % MOD

def mod_mul(a, b):
    return (a * b) % MOD

def mod_pow(a, p):
    return pow(a, p, MOD)

def mod_inv(a):
    return pow(a, MOD-2, MOD)

class Modular:
    def __init__(self, val=0):
        self.val = val % MOD
        if self.val < 0:
            self.val += MOD

    def __add__(self, other):
        if isinstance(other, Modular):
            return Modular(self.val + other.val)
        return Modular(self.val + other)

    def __sub__(self, other):
        if isinstance(other, Modular):
            return Modular(self.val - other.val)
        return Modular(self.val - other)

    def __mul__(self, other):
        if isinstance(other, Modular):
            return Modular(self.val * other.val)
        return Modular(self.val * other)

    def __truediv__(self, other):
        if isinstance(other, Modular):
            return Modular(self.val * mod_inv(other.val))
        return Modular(self.val * mod_inv(other))

    def __iadd__(self, other):
        self.val = (self.val + (other.val if isinstance(other, Modular) else other)) % MOD
        return self

    def __isub__(self, other):
        self.val = (self.val - (other.val if isinstance(other, Modular) else other)) % MOD
        return self

    def __imul__(self, other):
        self.val = (self.val * (other.val if isinstance(other, Modular) else other)) % MOD
        return self

    def __idiv__(self, other):
        self.val = (self.val * mod_inv(other.val if isinstance(other, Modular) else other)) % MOD
        return self

    def __neg__(self):
        return Modular(-self.val)

    def __eq__(self, other):
        return self.val == (other.val if isinstance(other, Modular) else other)

    def __ne__(self, other):
        return not self.__eq__(other)

    def __lt__(self, other):
        return self.val < (other.val if isinstance(other, Modular) else other)

    def __le__(self, other):
        return self.val <= (other.val if isinstance(other, Modular) else other)

    def __gt__(self, other):
        return self.val > (other.val if isinstance(other, Modular) else other)

    def __ge__(self, other):
        return self.val >= (other.val if isinstance(other, Modular) else other)

    def __int__(self):
        return self.val

    def __repr__(self):
        return str(self.val)

    def pow(self, p):
        return Modular(pow(self.val, p, MOD))

    def inv(self):
        return Modular(mod_inv(self.val))

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    prob = [Modular(0) for _ in range(N*N)]
    for i in range(N*N):
        percent = int(next(it))
        prob[i] = Modular(percent) * INV100

    mid = N // 2
    # maskValue: for each mask of 6 bits, map to index if popcount == mid else -1
    maskValue = [-1] * (1 << 6)
    cnt = 0
    for m in range(1 << 6):
        if bin(m).count('1') == mid:
            maskValue[m] = cnt
            cnt += 1
    sum_arr = [Modular(0) for _ in range(1 << cnt)]

    def process(L, R, handle):
        length = R - L
        # enumerate all edge selections for rows L..R-1
        for e in range(1 << (length * N)):
            pr = Modular(1)
            # compute probability of this edge selection
            tmp = e
            for i in range(L*N, R*N):
                bit = tmp & 1
                tmp >>= 1
                if bit:
                    pr *= prob[i]
                else:
                    pr *= (Modular(1) - prob[i])
                if pr.val == 0:
                    break
            if pr.val == 0:
                continue
            # enumerate all matchings (assign columns to rows)
            s = 0
            # generate all assignments of columns to rows (length rows)
            for assignment in itertools.product(range(N), repeat=length):
                # check that each edge is selected and columns are distinct
                mm = 0
                valid = True
                for idx, col in enumerate(assignment):
                    bit_pos = idx * N + col
                    if ((e >> bit_pos) & 1) == 0:
                        valid = False
                        break
                    if mm & (1 << col):
                        valid = False
                        break
                    mm |= (1 << col)
                if not valid:
                    continue
                if R == N:
                    mm ^= (1 << N) - 1
                idx_mask = maskValue[mm]
                if idx_mask != -1:
                    s |= (1 << idx_mask)
            handle(s, pr)

    # left half
    process(0, mid, lambda s, p: sum_arr.__setitem__(s, sum_arr[s] + p))

    # SOS DP over sum_arr
    n = len(sum_arr)
    d = 1
    while d < n:
        for i in range(n):
            if (i & d) == 0:
                sum_arr[i | d] += sum_arr[i]
        d <<= 1

    ans = Modular(0)
    total_mask = n - 1  # all bits set

    # right half
    def handle_right(s, p):
        nonlocal ans
        complement = total_mask ^ s
        ans += p * (sum_arr[-1] - sum_arr[complement])

    process(mid, N, handle_right)

    print(int(ans))

if __name__ == "__main__":
    main()
